/* @author MILO-GAO(高振銘)@2020 */ package page2020.util;import java.util.LinkedHashMap;import java.util.Map;import org.springframework.util.StringUtils;public class ParamUtil {	public final static Map<String, String> map(String parameter) {		Map<String, String> map = new LinkedHashMap<String, String>();		if (parameter != null) {			parameter = StringUtils.trimAllWhitespace(parameter);		}		if (parameter.length() == 0) {			return map;		}		String[] tokens = null;		if (parameter.indexOf(".") < 0) {			tokens = new String[] { parameter };		} else {			tokens = parameter.split(",");		}		for (int i=0; i < tokens.length; i++) {			String pairs = tokens[i];			int pos = pairs.indexOf("=");			if (pos > 0) {				String key = pairs.substring(0, pos);				String value = pairs.substring(pos + 1);				map.put(key, value);			}					}		return map;	}}